Item.method_code:
            Innovator inn = this.getInnovator();

            try
            {
                var thisId = this.getID();

                //現在の値を取得する
                var h4_rel_reqdoc = this.getProperty("h4_rel_reqdoc","");
                
                //前の値を取得し、変更されているかチェックする
                var getItem = inn.newItem(this.getType(),"get");
                getItem.setID(thisId);
                getItem.setAttribute("select", "h4_rel_reqdoc,h4_point_sub_number");
                getItem = getItem.apply();

                var h4_rel_reqdoc_be = getItem.getProperty("h4_rel_reqdoc","");
                var h4_point_sub_number = getItem.getProperty("h4_point_sub_number","");
                
                //空白から値をセットした場合は、枝番が1以外の場合はエラー
                if(String.IsNullOrEmpty(h4_rel_reqdoc_be) && !String.IsNullOrEmpty(h4_rel_reqdoc))
                {
                    if(h4_point_sub_number != "1")
                    {
                        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0604"));
                    }
                }
                else if(h4_rel_reqdoc_be =="" && h4_rel_reqdoc == "")
                {
                    //前後両方空白の場合、何もしない
                }
                else
                {
                    //// config_idで比較するように修正
                    // 現在の値を取得
                    var reqdoc_cfgId_itm = inn.newItem("h4_ReqDoc","get");
                    reqdoc_cfgId_itm.setID(h4_rel_reqdoc);
                    reqdoc_cfgId_itm.setAttribute("select", "config_id");
                    reqdoc_cfgId_itm = reqdoc_cfgId_itm.apply();
                    var reqdoc_cfgId = reqdoc_cfgId_itm.getProperty("config_id","");
                    
                    // 前の値を取得
                    var reqdoc_be_cfgId_itm = inn.newItem("h4_ReqDoc","get");
                    reqdoc_be_cfgId_itm.setID(h4_rel_reqdoc_be);
                    reqdoc_be_cfgId_itm.setAttribute("select", "config_id");
                    reqdoc_be_cfgId_itm = reqdoc_be_cfgId_itm.apply();
                    var reqdoc_be_cfgId = reqdoc_be_cfgId_itm.getProperty("config_id","");
                    ////
                    
                    //それ以外の場合はエラー
                    if(reqdoc_cfgId != reqdoc_be_cfgId)
                    {
                        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0605"));
                    }
                }
                
                return this;
            }
            catch (Exception e)
            {
                // Item err = inn.newError("Error01:" + e.Message);
                // err.setErrorDetail(e.StackTrace);
                // return err;
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
            }
        }

